      summary: summary,
      firstKeptEntryId: preparation.firstKeptEntryId,
      tokensBefore: preparation.tokensBefore,
      details: {
        'readFiles': preparation.readFiles,
        'modifiedFiles': preparation.modifiedFiles,
        if (sanitized.stripped.isNotEmpty)
